// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v2/clients", wrapper.GetClients)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v2/clients", wrapper.CreateClient)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/api/v2/clients/{id}", wrapper.DeleteClient)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v2/clients/{id}", wrapper.GetClient)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/api/v2/clients/{id}", wrapper.UpdateClient)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v2/clients/{id}/rotate-secret", wrapper.RotateClientSecret)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v2/resource-servers", wrapper.GetResourceServers)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v2/resource-servers", wrapper.CreateResourceServer)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/api/v2/resource-servers/{id}", wrapper.DeleteResourceServer)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v2/resource-servers/{id}", wrapper.GetResourceServer)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/api/v2/resource-servers/{id}", wrapper.UpdateResourceServer)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/system/tenants", wrapper.GetTenants)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/system/tenants", wrapper.CreateTenant)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/api/system/tenants/{name}", wrapper.DeleteTenant)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/api/system/tenants/{name}", wrapper.UpdateTenant)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/system/operators", wrapper.GetOperators)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/system/operators", wrapper.CreateOperator)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/api/system/operators/{id}", wrapper.DeleteOperator)
	})

	return r
}
